-- Create views for typed fact tables over raw_ingest
CREATE VIEW events_view AS
SELECT T1.ts, T1.machine_id, T1.reason_code, T1.duration_s, T1.energy_kwh FROM raw_ingest AS T1 INNER JOIN tag_map AS T2 ON T1.payload->>'tag' = T2.tag_id WHERE T1.payload->>'type' = 'event';

CREATE VIEW samples_view AS
SELECT T1.ts, T1.machine_id, T1.tag, T1.value FROM raw_ingest AS T1 INNER JOIN tag_map AS T2 ON T1.payload->>'tag' = T2.tag_id WHERE T1.payload->>'type' = 'sample';
